            <?php $bookingHistorySearch = $viewKey === 'bookingHistory'; ?>
            <section class="amenity-booking-history" id="<?= $viewKey ?>" <?= $bookingHistorySearch ? 'data-history-search' : '' ?>><div class="amenity-section-heading"><h2><?= $bookingHistorySearch ? 'Booking history' : 'Booking requests' ?></h2><p <?= $bookingHistorySearch ? 'id="bookingHistorySearchCount" role="status" aria-live="polite"' : '' ?>><span <?= $bookingHistorySearch ? 'data-history-search-count' : '' ?>><?= count($bookings) ?></span> matching reservation(s)</p></div>
                <form class="amenity-admin-filter" method="get" action="bookingrequest.php#<?= $viewKey ?>"><?php if ($bookingHistorySearch): ?><label class="field-label amenity-history-search" for="bookingHistorySearch">Search booking history<input id="bookingHistorySearch" type="search" name="history_search" data-history-search-input value="<?= $escape(is_string($_GET['history_search'] ?? null) ? $_GET['history_search'] : '') ?>" placeholder="Resident, unit, amenity, date or booking number" aria-describedby="bookingHistorySearchCount"></label><?php endif; ?><label class="field-label">Booking status<select name="status"><option value="all">All statuses</option><?php foreach($panelStatuses as $value): ?><option value="<?= $escape($value) ?>" <?= $panelStatus===$value?'selected':'' ?>><?= ucfirst($value) ?></option><?php endforeach; ?></select></label><button class="service-btn" type="submit">Apply filter</button></form>
                <?php if ($bookingHistorySearch): ?><p data-history-search-empty hidden>No bookings match your search.</p><?php endif; ?>
                <p class="amenity-payment-note">Scroll to see all columns. Pending pool requests do not hold hours. Paid or online-checkout cancellations require PMO and billing review.</p>
                <div class="amenity-admin-table-wrap" role="region" aria-label="<?= $viewKey === 'bookingHistory' ? 'Amenity booking history' : 'Amenity booking requests' ?>" tabindex="0"><table class="amenity-admin-table"><thead><tr><th scope="col">Booking</th><th scope="col">Resident / Tenant</th><th scope="col">Unit</th><th scope="col">Date</th><th scope="col">Start – End</th><th scope="col">Duration</th><th scope="col">Total fee</th><th scope="col">Booking status</th><th scope="col">Payment</th><th scope="col">Details &amp; Actions</th></tr></thead><tbody>
                <?php if(!$bookings): ?><tr><td colspan="10">No reservations match this status.</td></tr><?php endif; ?>
                <?php foreach($bookings as $booking):
                    $future=$booking['booking_date'].' '.$booking['booking_time']>date('Y-m-d H:i:s');
                    $review=$booking['payment_id'] && ($booking['payment_status']==='paid' || $booking['paymongo_checkout_id']);
                    $active=in_array($booking['status'],['pending','approved','confirmed'],true);
                ?>
                    <tr<?php if ($bookingHistorySearch): ?> data-history-search-record="<?= $escape(implode(' ', ['#'.$booking['id'], $booking['full_name'], $booking['username'], $booking['unit_number'], $booking['amenity'], $booking['booking_date'], date('M j, Y', strtotime($booking['booking_date'])), $booking['status'], $booking['payment_status'] ?? '', $booking['payment_id'] ? 'Bill #'.$booking['payment_id'] : ''])) ?>"<?php endif; ?>><td><strong>#<?= (int)$booking['id'] ?></strong><span><?= $escape($booking['amenity']) ?></span></td><td><strong><?= $escape($booking['full_name']) ?></strong><span><?= $escape($booking['account_type'] ?: 'Resident Owner') ?></span></td><td><?= $escape($booking['unit_number']) ?></td><td><?= $escape(date('M j, Y',strtotime($booking['booking_date']))) ?></td><td><?= $escape(date('g:i A',strtotime($booking['booking_time']))) ?> – <?= $escape($booking['end_time']?date('g:i A',strtotime($booking['end_time'])):'—') ?></td><td><?= $booking['duration_hours']?(int)$booking['duration_hours'].' hour(s)':'Full day' ?></td><td>₱<?= number_format((float)$booking['total_fee'],2) ?></td><td><span class="amenity-status amenity-status-<?= $escape($booking['status']) ?>"><?= ucfirst($booking['status']) ?></span></td><td><?= $booking['payment_id']?$escape($booking['payment_status']==='pending'?'Unpaid':($booking['payment_status']==='rejected'?'Voided':ucfirst($booking['payment_status']))):'No auto bill' ?><?php if($booking['payment_id']): ?><span>Bill #<?= (int)$booking['payment_id'] ?></span><?php endif; ?></td><td>
                        <details class="amenity-decision-details"><summary>View details / actions</summary><p><?= (int)$booking['attendees'] ?> guest(s) · Unit <?= $escape($booking['unit_number']) ?></p><p>Rate snapshot: ₱<?= number_format((float)$booking['hourly_rate'],2) ?>/hour</p><p>Approved: <?= $escape($booking['approved_at'] ?: 'Not yet approved') ?><?= $booking['approved_by']?' · Staff #'.(int)$booking['approved_by']:'' ?></p>
                        <?php if($booking['rejection_reason'] || $booking['cancellation_note']): ?><p><?= $escape($booking['rejection_reason'] ?: $booking['cancellation_note']) ?></p><?php endif; ?>
                        <?php if($active): ?><form method="post" action="bookingrequest.php#<?= $viewKey ?>" data-booking-decision="<?= (int)$booking['id'] ?>"><?= workflowCsrfField() ?><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><label class="field-label">Reason / PMO notes<textarea name="reason" maxlength="500" rows="3" placeholder="Required for rejection or PMO cancellation"></textarea></label>
                            <?php if($review && canManageBilling()): ?><label class="field-label amenity-pmo-checkbox"><input type="checkbox" name="pmo_review"> PMO reviewed cancellation; preserve this bill for financial/refund review.</label><?php endif; ?>
                            <div class="amenity-decision-buttons"><?php if($booking['status']==='pending' && $future): ?><button class="service-btn" type="submit" name="status" value="approved">Approve</button><button class="service-btn service-btn-danger" type="submit" name="status" value="rejected">Reject</button><?php endif; ?>
                            <?php if($future && (!$review || canManageBilling())): ?><button class="service-btn service-btn-secondary" type="submit" name="status" value="cancelled"><?= $review?'PMO cancellation':'Cancel' ?></button><?php endif; ?>
                            <?php if(in_array($booking['status'],['approved','confirmed'],true) && $booking['booking_date'].' '.$booking['end_time']<=date('Y-m-d H:i:s')): ?><button class="service-btn service-btn-secondary" type="submit" name="status" value="completed">Mark completed</button><?php endif; ?></div><p data-decision-feedback role="status" aria-live="polite"></p>
                        </form><?php endif; ?></details>
                    </td></tr>
                <?php endforeach; ?></tbody></table></div>
            </section>
